56	/**
57	 * @author Vitaliy Fedoriv
58	 */
59	
60	@RestController
61	@CrossOrigin(exposedHeaders = "errors, content-type")
62	@RequestMapping("/api")
63	public class OwnerRestControllerV1 implements OwnersApi {
64	
65	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
66	
67	    private final ClinicService clinicService;
68	
69	    private final OwnerMapper ownerMapper;
70	
71	    private final PetMapper petMapper;
72	
73	    private final VisitMapper visitMapper;
74	
75	    private final AddressNormalizer addressNormalizer;
76	
77	    public OwnerRestControllerV1(ClinicService clinicService,
78	                                 OwnerMapper ownerMapper,
79	                                 PetMapper petMapper,
80	                                 VisitMapper visitMapper,
81	                                 AddressNormalizer addressNormalizer) {
82	        this.clinicService = clinicService;
83	        this.ownerMapper = ownerMapper;
84	        this.petMapper = petMapper;
85	        this.visitMapper = visitMapper;
86	        this.addressNormalizer = addressNormalizer;
87	    }
88	
89	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
90	    @Override
91	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
92	        Collection<Owner> owners;
93	        if (lastName != null) {
94	            owners = this.clinicService.findOwnerByLastName(lastName);
95	        } else {
96	            owners = this.clinicService.findAllOwners();
97	        }
98	        if (owners.isEmpty()) {
99	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
100	        }
101	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
102	    }
103	
104	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
105	    @Override
106	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
107	        Owner owner = this.clinicService.findOwnerById(ownerId);
108	        if (owner == null) {
109	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
110	        }
111	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
112	    }
113	
114	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
115	    @Override
116	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
117	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
118	
119	        HttpStatus invalid = normalizeAndValidate(owner);
120	        if (invalid != null) {
121	            return new ResponseEntity<>(invalid);
122	        }
123	        if (isDailyLimitReached(owner.getRegistrationDate())) {
124	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
125	        }
126	
127	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
128	        assignHousehold(owner);
129	
130	        HttpStatus conflict = checkForConflicts(owner, sharesHousehold);
131	        if (conflict != null) {
132	            return new ResponseEntity<>(conflict);
133	        }
134	
135	        assignDerivedAttributes(owner, sharesHousehold);
136	        this.clinicService.saveOwner(owner);
137	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
138	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
139	        return created(owner);
140	    }
141	
142	    /**
143	     * Bring a freshly mapped owner into its canonical, valid form, or report the reason it must be
144	     * rejected. The owner's address is normalized (a blank address is rejected), its telephone is
145	     * converted to E.164 (an unconvertible number is rejected), its postcode is checked against its
146	     * city's region, a registration date in the future is rejected, and the effective registration
147	     * date (the supplied one, or today when none was given) is rolled onto a business day and stored
148	     * back on the owner. Returns {@code null} once the owner is valid and normalized, or the
149	     * {@link HttpStatus} the create must fail with ({@code 400 Bad Request}) otherwise.
150	     */
151	    private HttpStatus normalizeAndValidate(Owner owner) {
152	        String address = addressNormalizer.normalize(owner.getAddress());
153	        if (address.isEmpty()) {
154	            return HttpStatus.BAD_REQUEST;
155	        }
156	        owner.setAddress(address);
157	        String telephone = toE164(owner.getTelephone());
158	        if (telephone == null) {
159	            return HttpStatus.BAD_REQUEST;
160	        }
161	        owner.setTelephone(telephone);
162	        if (isDisposableEmail(owner.getEmail())) {
163	            return HttpStatus.BAD_REQUEST;
164	        }
165	        if (!owner.isPostcodeValid()) {
166	            return HttpStatus.BAD_REQUEST;
167	        }
168	        if (owner.getRegistrationDate() != null
169	            && owner.getRegistrationDate().isAfter(LocalDate.now())) {
170	            return HttpStatus.BAD_REQUEST;
171	        }
172	        LocalDate effectiveDate = owner.getRegistrationDate() != null
173	            ? owner.getRegistrationDate() : LocalDate.now();
174	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
175	        return null;
176	    }
177	
178	    /**
179	     * The set of disposable (throwaway) email domains that an owner's email may not use. An owner
180	     * whose email is hosted on one of these domains is rejected with {@code 400 Bad Request}.
181	     */
182	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
183	        "mailinator.com", "tempmail.com", "guerrillamail.com");
184	
185	    /**
186	     * Whether the given email is hosted on a {@linkplain #DISPOSABLE_EMAIL_DOMAINS disposable}
187	     * domain. The email is optional, so a {@code null} or empty email is not disposable; otherwise
188	     * the domain (the part after the last {@code '@'}, compared case-insensitively) is matched
189	     * against the blocklist.
190	     */
191	    private boolean isDisposableEmail(String email) {
192	        if (email == null || email.isEmpty()) {
193	            return false;
194	        }
195	        int at = email.lastIndexOf('@');
196	        if (at < 0) {
197	            return false;
198	        }
199	        String domain = email.substring(at + 1).toLowerCase();
200	        return DISPOSABLE_EMAIL_DOMAINS.contains(domain);
201	    }
202	
203	    /**
204	     * Assign the owner its household link. The {@link #householdId(Owner) householdId} is computed
205	     * deterministically from the owner's lastName and postcode, so every owner sharing that
206	     * lastName and postcode is assigned the same value automatically, independent of whether the
207	     * owner declares it shares a household. The link is assigned before the
208	     * {@link #checkForConflicts(Owner, boolean) conflict checks} because it is part of the owner's
209	     * {@link Owner#getIdentityKey() identity} and feeds its {@link #householdSize(String) household
210	     * size}.
211	     */
212	    private void assignHousehold(Owner owner) {
213	        owner.setHouseholdId(householdId(owner));
214	    }
215	
216	    /**
217	     * Whether the owner clashes with an owner that already exists, and the {@link HttpStatus} the
218	     * create must fail with when it does. An owner is rejected with {@code 409 Conflict} when it
219	     * {@link #isHouseholdDuplicate(Owner) duplicates an existing household} or when its
220	     * {@link #isCityAtCapacity(String) city is already at capacity}. Declaring {@code
221	     * sharesHousehold} bypasses only the household-duplicate block (the owner is then created as a
222	     * declared household member); it does not lift the city-capacity limit. Returns {@code null}
223	     * when the owner clashes with nothing and may be created.
224	     */
225	    private HttpStatus checkForConflicts(Owner owner, boolean sharesHousehold) {
226	        if (!sharesHousehold && isHouseholdDuplicate(owner)) {
227	            return HttpStatus.CONFLICT;
228	        }
229	        if (isCityAtCapacity(owner.getCity())) {
230	            return HttpStatus.CONFLICT;
231	        }
232	        return null;
233	    }
234	
235	    /**
236	     * Build the {@code 201 Created} response for a persisted owner: its {@link OwnerDto} body and a
237	     * {@code Location} header pointing at {@code /api/owners/{id}}.
238	     */
239	    private ResponseEntity<OwnerDto> created(Owner owner) {
240	        HttpHeaders headers = new HttpHeaders();
241	        headers.setLocation(UriComponentsBuilder.newInstance()
242	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
243	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), headers, HttpStatus.CREATED);
244	    }
245	
246	    /**
247	     * Assign the attributes that are derived once, at creation time, and stored on the owner: its
248	     * {@link #customerCode(Owner) customerCode}, {@link #namesakeCount(String, String) namesakeCount},
249	     * {@link #isBulkSignup(LocalDate) bulk-signup warning} and {@link #householdSize(String)
250	     * householdSize}. Each is computed from the owner's own fields together with the owners already
251	     * present, so this runs after the owner has been validated and has passed the duplicate and
252	     * capacity checks, and immediately before it is persisted.
253	     */
254	    private void assignDerivedAttributes(Owner owner, boolean sharesHousehold) {
255	        owner.setCustomerCode(customerCode(owner));
256	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
257	        owner.setBulkSignupWarning(isBulkSignup(owner.getRegistrationDate()));
258	        owner.setHouseholdSize(householdSize(owner.getHouseholdId()));
259	        assignPossibleDuplicate(owner, sharesHousehold);
260	    }
261	
262	    /**
263	     * Flag a newly created owner as a possible (soft) duplicate. An owner that declares it shares a
264	     * household ({@code sharesHousehold}) is a declared household member, not a suspected duplicate,
265	     * so it is never flagged. Otherwise, because this runs after the hard
266	     * {@link #isHouseholdDuplicate(Owner) household-duplicate} check, the owner is not a household
267	     * match; it is flagged only when it is a soft match of an existing owner as determined by
268	     * {@link #findSoftDuplicate(Owner)}. When such an owner exists the new owner is flagged with
269	     * {@code possibleDuplicate = true} and {@code possibleDuplicateOf} set to that owner's id;
270	     * otherwise {@code possibleDuplicate = false} and no matching id is recorded.
271	     */
272	    private void assignPossibleDuplicate(Owner owner, boolean sharesHousehold) {
273	        Owner match = sharesHousehold ? null : findSoftDuplicate(owner);
274	        owner.setPossibleDuplicate(match != null);
275	        owner.setPossibleDuplicateOf(match == null ? null : match.getId());
276	    }
277	
278	    /**
279	     * The existing owner this owner softly duplicates, or {@code null} when there is none. A soft
280	     * match is an existing owner that shares this owner's lastName (compared case-insensitively,
281	     * with collapsed whitespace) and its postcode but carries a different telephone; the earliest
282	     * such owner (by id) is returned. A postcode is required for a soft match, so an owner without a
283	     * postcode never matches.
284	     */
285	    private Owner findSoftDuplicate(Owner owner) {
286	        if (owner.getPostcode() == null) {
287	            return null;
288	        }
289	        String candidateLastName = normalizeName(owner.getLastName());
290	        return this.clinicService.findAllOwners().stream()
291	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
292	            .filter(existing -> normalizeName(existing.getLastName()).equals(candidateLastName))
293	            .filter(existing -> !owner.getTelephone().equals(existing.getTelephone()))
294	            .min(Comparator.comparingInt(Owner::getId))
295	            .orElse(null);
296	    }
297	
298	    /**
299	     * Build the customer code for a newly created owner, formatted {@code '<REGION>-<HASH8>'}
300	     * where REGION is the region derived from the owner's postcode (or {@link Owner#UNKNOWN_REGION}
301	     * when the postcode is absent or maps to no known region) and HASH8 is the first 8 upper-case
302	     * hex characters of the SHA-256 of the normalized (E.164) telephone concatenated with the
303	     * lastName (e.g. {@code 'NSW-3C1A9F2B'}). This is the single source of the owner's identity:
304	     * every value built from the customer code (the membership number and its check digit) and the
305	     * owner's locality are derived from it.
306	     */
307	    private String customerCode(Owner owner) {
308	        String region = owner.getRegion() != null ? owner.getRegion() : Owner.UNKNOWN_REGION;
309	        String hash8 = shaHexUpper(owner.getTelephone() + owner.getLastName()).substring(0, 8);
310	        return region + "-" + hash8;
311	    }
312	
313	    /**
314	     * Whether the per-day owner creation limit has been reached for the given business day, i.e.
315	     * 100 or more owners already carry that {@code registrationDate}. The day is the adjusted
316	     * (business-day) registration date of the owner being created, so owners are counted per
317	     * business day. When true, a new owner must be rejected with {@code 429 Too Many Requests}.
318	     */
319	    private boolean isDailyLimitReached(LocalDate day) {
320	        long count = this.clinicService.findAllOwners().stream()
321	            .filter(existing -> day.equals(existing.getRegistrationDate()))
322	            .count();
323	        return count >= 100;
324	    }
325	
326	    /**
327	     * Whether creating this owner pushes the day's total past the bulk-signup threshold, i.e.
328	     * more than 80 owners have already been created for the given business day. Counts the owners
329	     * already carrying that {@code registrationDate} (the same accumulation as the daily-limit
330	     * rule); when that count exceeds 80 the newly created owner is flagged with a bulk-signup
331	     * warning.
332	     */
333	    private boolean isBulkSignup(LocalDate day) {
334	        long count = this.clinicService.findAllOwners().stream()
335	            .filter(existing -> day.equals(existing.getRegistrationDate()))
336	            .count();
337	        return count > 80;
338	    }
339	
340	    /**
341	     * Roll a registration date forward onto a business day: when it falls on a Saturday or Sunday,
342	     * advance it to the following Monday; a weekday is returned unchanged.
343	     */
344	    private LocalDate toBusinessDay(LocalDate date) {
345	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
346	            date = date.plusDays(1);
347	        }
348	        return date;
349	    }
350	
351	    /**
352	     * Whether the given city has reached its owner capacity, i.e. it already contains 50 or
353	     * more owners. Cities are compared case-insensitively.
354	     */
355	    private boolean isCityAtCapacity(String city) {
356	        long count = this.clinicService.findAllOwners().stream()
357	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
358	            .count();
359	        return count >= 50;
360	    }
361	
362	    /**
363	     * The number of existing owners that already share the given firstName and lastName,
364	     * compared case-insensitively (and with surrounding whitespace trimmed and internal
365	     * whitespace runs collapsed). Counted over the owners present before this create.
366	     */
367	    private int namesakeCount(String firstName, String lastName) {
368	        String candidateFirstName = normalizeName(firstName);
369	        String candidateLastName = normalizeName(lastName);
370	        return (int) this.clinicService.findAllOwners().stream()
371	            .filter(existing -> normalizeName(existing.getFirstName()).equals(candidateFirstName)
372	                && normalizeName(existing.getLastName()).equals(candidateLastName))
373	            .count();
374	    }
375	
376	    /**
377	     * The number of members in this owner's household after this create: the count of existing
378	     * owners already carrying the same non-null {@code householdId} plus one for the owner being
379	     * created. An owner with no household ({@code householdId == null}) is a household of one.
380	     * Owners sharing a household are matched by their assigned {@code householdId}, so the count
381	     * does not depend on the order in which household members were created.
382	     */
383	    private int householdSize(String householdId) {
384	        if (householdId == null) {
385	            return 1;
386	        }
387	        long existing = this.clinicService.findAllOwners().stream()
388	            .filter(other -> householdId.equals(other.getHouseholdId()))
389	            .count();
390	        return (int) existing + 1;
391	    }
392	
393	    /**
394	     * Convert a raw telephone input to its E.164 representation, or {@code null} if it
395	     * cannot form a valid E.164 number.
396	     *
397	     * <p>A leading '+' and country code are kept when present; otherwise country code
398	     * '+61' is assumed and a single leading '0' is dropped from the national digits.
399	     * Spaces, dashes and brackets (indeed any non-digit) are stripped. The result must
400	     * carry 8 to 15 digits after the '+', and — for a recognised country calling code —
401	     * exactly the national-digit count that code requires (see
402	     * {@link Owner#hasValidNationalLength}); otherwise it is rejected as invalid.
403	     */
404	    private String toE164(String telephone) {
405	        if (telephone == null) {
406	            return null;
407	        }
408	        boolean hasCountryCode = telephone.trim().startsWith("+");
409	        String digits = telephone.replaceAll("\\D", "");
410	        String e164;
411	        if (hasCountryCode) {
412	            e164 = digits;
413	        } else {
414	            if (digits.startsWith("0")) {
415	                digits = digits.substring(1);
416	            }
417	            e164 = "61" + digits;
418	        }
419	        if (e164.length() < 8 || e164.length() > 15) {
420	            return null;
421	        }
422	        if (!Owner.hasValidNationalLength(e164)) {
423	            return null;
424	        }
425	        return "+" + e164;
426	    }
427	
428	    /**
429	     * Whether the candidate owner belongs to a household that already exists, and so must be
430	     * rejected with {@code 409 Conflict} unless it declares {@code sharesHousehold}. The household
431	     * is keyed by the deterministic {@link #householdId(Owner) householdId} (derived from lastName
432	     * and postcode), so any existing owner carrying the same householdId means this owner is a
433	     * second member of an already-registered household. Two owners sharing a lastName and postcode
434	     * are therefore the same household: the second is a household duplicate.
435	     */
436	    private boolean isHouseholdDuplicate(Owner owner) {
437	        String householdId = owner.getHouseholdId();
438	        if (householdId == null) {
439	            return false;
440	        }
441	        return this.clinicService.findAllOwners().stream()
442	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
443	    }
444	
445	    /**
446	     * Normalize an owner's name for household comparison: trim, collapse internal whitespace runs
447	     * to a single space and lower-case. A null value normalizes to the empty string.
448	     */
449	    private String normalizeName(String value) {
450	        if (value == null) {
451	            return "";
452	        }
453	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
454	    }
455	
456	    /**
457	     * A stable shared identifier for the household an owner belongs to, derived deterministically
458	     * from its lastName and postcode. The lastName is normalized (case-insensitive,
459	     * whitespace-collapsed) before hashing, so every owner sharing the same lastName and postcode is
460	     * assigned the same value regardless of the order in which they are created. Formatted as the
461	     * first 12 upper-case hex characters of the SHA-256 of {@code '<normalizedLastName>|<postcode>'}
462	     * (an absent postcode contributes the empty string).
463	     */
464	    private String householdId(Owner owner) {
465	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
466	        String key = normalizeName(owner.getLastName()) + "|" + postcode;
467	        return shaHexUpper(key).substring(0, 12);
468	    }
469	
470	    /**
471	     * The SHA-256 digest of {@code input}'s UTF-8 bytes, rendered as an upper-case hexadecimal
472	     * string (two hex characters per digest byte, so 64 characters in all). This is the single
473	     * place the hashing-and-hex-encoding is performed; callers that need a shorter opaque token
474	     * take a prefix of the result (e.g. {@link #householdId} keeps the first 12 characters and
475	     * {@link #customerCode} keeps the first 8).
476	     */
477	    private String shaHexUpper(String input) {
478	        try {
479	            byte[] digest = MessageDigest.getInstance("SHA-256")
480	                .digest(input.getBytes(StandardCharsets.UTF_8));
481	            StringBuilder sb = new StringBuilder(digest.length * 2);
482	            for (byte b : digest) {
483	                sb.append(String.format("%02x", b));
484	            }
485	            return sb.toString().toUpperCase();
486	        }
487	        catch (NoSuchAlgorithmException e) {
488	            throw new IllegalStateException("SHA-256 not available", e);
489	        }
490	    }
491	
492	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
493	    @Override
494	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
495	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
496	        if (currentOwner == null) {
497	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
498	        }
499	        currentOwner.setAddress(ownerFieldsDto.getAddress());
500	        currentOwner.setCity(ownerFieldsDto.getCity());
501	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
502	        currentOwner.setLastName(ownerFieldsDto.getLastName());
503	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
504	        this.clinicService.saveOwner(currentOwner);
505	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
506	    }
507	
508	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
509	    @Transactional
510	    @Override
511	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
512	        Owner owner = this.clinicService.findOwnerById(ownerId);
513	        if (owner == null) {
514	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
515	        }
516	        this.clinicService.deleteOwner(owner);
517	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
518	    }
519	
520	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
521	    @Override
522	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
523	        Owner owner = this.clinicService.findOwnerById(ownerId);
524	        if (owner == null) {
525	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
526	        }
527	        HttpHeaders headers = new HttpHeaders();
528	        Pet pet = petMapper.toPet(petFieldsDto);
529	        owner.setId(ownerId);
530	        pet.setOwner(owner);
531	        pet.getType().setName(null);
532	        this.clinicService.savePet(pet);
533	        PetDto petDto = petMapper.toPetDto(pet);
534	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
535	            .buildAndExpand(pet.getId()).toUri());
536	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
537	    }
538	
539	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
540	    @Override
541	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
542	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
543	        if (currentOwner != null) {
544	            Pet currentPet = this.clinicService.findPetById(petId);
545	            if (currentPet != null) {
546	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
547	                currentPet.setName(petFieldsDto.getName());
548	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
549	                this.clinicService.savePet(currentPet);
550	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
551	            }
552	        }
553	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
554	    }
