556	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
557	    @Override
558	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
559	        HttpHeaders headers = new HttpHeaders();
560	        Visit visit = visitMapper.toVisit(visitFieldsDto);
