331	    }
332	
333	    /**
334	     * The region whose fixed {@linkplain #REGION_POSTCODE_RANGE postcode range} contains the
335	     * given postcode, or {@code null} when the postcode is {@code null}, not four digits, or in
336	     * no known range.
337	     */
338	    private static String regionOfPostcode(String postcode) {
339	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
340	            return null;
341	        }
342	        int value = Integer.parseInt(postcode);
343	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGE.entrySet()) {
344	            int[] range = entry.getValue();
345	            if (value >= range[0] && value <= range[1]) {
346	                return entry.getKey();
347	            }
348	        }
349	        return null;
350	    }
351	
352	    /**
353	     * Fixed inclusive 4-digit postcode ranges keyed by region, as {@code {low, high}}:
354	     * {@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}. A region not
355	     * listed here (i.e. {@link #UNKNOWN_REGION}) accepts any 4-digit postcode.
356	     */
357	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
358	        "NSW", new int[] {2000, 2099},
359	        "VIC", new int[] {3000, 3099},
360	        "QLD", new int[] {4000, 4099});
361	
362	    /**
363	     * Whether this owner's postcode is acceptable for its city. Postcode is optional, so a
364	     * {@code null} postcode is accepted. When present it must be four digits and, for a city
365	     * whose {@linkplain #regionOf(String) region} is known, fall within that region's fixed
366	     * inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}); a
367	     * city with no known region accepts any 4-digit postcode.
368	     */
369	    public boolean isPostcodeValid() {
370	        if (this.postcode == null) {
371	            return true;
372	        }
373	        if (!this.postcode.matches("[0-9]{4}")) {
374	            return false;
375	        }
376	        int[] range = REGION_POSTCODE_RANGE.get(regionOf(this.city));
377	        if (range == null) {
378	            return true;
379	        }
380	        int value = Integer.parseInt(this.postcode);
381	        return value >= range[0] && value <= range[1];
382	    }
