384	    /**
385	     * The national (subscriber) digit count required by each known country calling code, keyed by
386	     * the code's digits (without the leading {@code '+'}): {@code '+1'} carries 10 national digits
387	     * and {@code '+61'} carries 9. This is the single source of the country-calling-code table,
388	     * shared by every rule keyed by an E.164 number's country code so the mapping is never
389	     * re-derived elsewhere.
390	     */
391	    private static final Map<String, Integer> NATIONAL_DIGITS_BY_COUNTRY = Map.of(
392	        "1", 10,
393	        "61", 9);
394	
395	    /**
396	     * The country calling code (its digits, without the leading {@code '+'}) that prefixes the given
397	     * E.164 digit string, choosing the longest matching code known to
398	     * {@link #NATIONAL_DIGITS_BY_COUNTRY}, or {@code null} when the number begins with no known
399	     * country code. This is the single place a country code is read from an E.164 number, so every
400	     * rule keyed by that code shares one derivation.
401	     */
402	    private static String countryCodeOf(String e164Digits) {
403	        return NATIONAL_DIGITS_BY_COUNTRY.keySet().stream()
404	            .filter(e164Digits::startsWith)
405	            .max(Comparator.comparingInt(String::length))
406	            .orElse(null);
407	    }
408	
409	    /**
410	     * Whether the E.164 digit string (no leading {@code '+'}) carries the national-number length
411	     * required by its {@linkplain #countryCodeOf(String) country calling code}. The longest matching
412	     * known code wins; a number whose country code is not recognised passes this check (its length is
413	     * then governed only by the general E.164 bound), while a recognised code must be followed by
414	     * exactly the national-digit count it requires ({@code '+1'} 10, {@code '+61'} 9).
415	     */
416	    public static boolean hasValidNationalLength(String e164Digits) {
417	        String countryCode = countryCodeOf(e164Digits);
418	        if (countryCode == null) {
419	            return true;
420	        }
421	        return e164Digits.length() - countryCode.length() == NATIONAL_DIGITS_BY_COUNTRY.get(countryCode);
422	    }
423	
424	    /**
425	     * The owner's membership points: they start at 0, gain 2 when an email is present, gain 1 when
426	     * namesakeCount is 0, gain 2 for a {@linkplain #hasLargeHousehold() household of 3 or more}, and
427	     * gain 3 when the owner's {@linkplain #getTenureDays() tenure} exceeds 365 days. The email,
428	     * namesake and household factors are available on creation; the tenure factor is reached only
429	     * once tenure grows beyond 365 days.
430	     */
431	    public Integer getMembershipPoints() {
432	        int points = 0;
433	        if (hasEmail()) {
434	            points += 2;
435	        }
436	        if (hasNoNamesakes()) {
437	            points += 1;
438	        }
439	        if (hasLargeHousehold()) {
440	            points += 2;
441	        }
442	        if (hasTenureBeyondOneYear()) {
443	            points += 3;
444	        }
445	        return points;
446	    }
447	
448	    /**
449	     * The owner's membership level, a number from 1 to 4 derived from {@linkplain #getMembershipPoints()
450	     * membershipPoints}: level 1 for 0-1 points, level 2 for 2-3, level 3 for 4-5, and level 4 for 6 or
451	     * more.
452	     */
453	    public Integer getMembershipLevel() {
454	        int points = getMembershipPoints();
455	        if (points >= 6) {
456	            return 4;
457	        }
458	        if (points >= 4) {
459	            return 3;
460	        }
461	        if (points >= 2) {
462	            return 2;
463	        }
464	        return 1;
465	    }
466	
467	    /**
468	     * Whether this owner belongs to a household of three or more: its {@link #getHouseholdSize()
469	     * householdSize} is {@code 3} or greater. A {@code null} householdSize, meaning the size is not
470	     * known, is treated as not a large household.
471	     */
472	    private boolean hasLargeHousehold() {
473	        return this.householdSize != null && this.householdSize >= 3;
474	    }
475	
476	    /**
477	     * Whether this owner has an email on record: a non-{@code null}, non-empty {@link #getEmail()
478	     * email}. This is the single source of the "has an email" test, shared by every rule keyed by
479	     * email presence so the check is never re-derived elsewhere.
480	     */
481	    private boolean hasEmail() {
482	        return this.email != null && !this.email.isEmpty();
483	    }
484	
485	    /**
486	     * Whether this owner's name is unique in the clinic: its {@link #getNamesakeCount() namesakeCount}
487	     * is {@code 0} (no other owner shares the name). A {@code null} namesakeCount, meaning the count is
488	     * not known, is treated as not unique.
489	     */
490	    private boolean hasNoNamesakes() {
491	        return this.namesakeCount != null && this.namesakeCount == 0;
492	    }
493	
494	    /**
495	     * Whether this owner's {@linkplain #getTenureDays() tenure} exceeds 365 days. A newly created owner
496	     * (zero tenure) does not qualify; the threshold is crossed only once tenure grows beyond one year.
497	     */
498	    private boolean hasTenureBeyondOneYear() {
499	        return this.getTenureDays() > 365;
500	    }
501	
502	    /**
503	     * The owner's tenure in whole days: the number of days between the {@link #registrationDate} and
504	     * the current date, or {@code 0} when the registrationDate is not yet set (a newly created owner has
505	     * zero tenure). Never negative.
506	     */
507	    public long getTenureDays() {
508	        if (this.registrationDate == null) {
509	            return 0;
510	        }
511	        return Math.max(0, ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now()));
512	    }
513	
514	    /**
515	     * The owner's preferred contact channel: {@code 'EMAIL'} when an email is present,
516	     * otherwise {@code 'PHONE'}.
517	     */
518	    public String getContactPreference() {
519	        return hasEmail() ? "EMAIL" : "PHONE";
520	    }
521	
522	    /**
523	     * The owner's stored E.164 {@linkplain #getTelephone() telephone} formatted for humans:
524	     * a {@code '+'}, the {@linkplain #countryCodeOf(String) country calling code}, a space, and
525	     * the national digits grouped into threes from the left separated by spaces,
526	     * e.g. {@code '+61412345678'} -> {@code '+61 412 345 678'}. The raw {@link #getTelephone()
